                        case 0x0100:
                            position.set(Position.KEY_ODOMETER_TRIP, buf.readUnsignedShort() * 0.1);
                            break;
                        case 0x0102:
                            position.set("tripFuel", buf.readUnsignedShort() * 0.1);
                            break;
